class Solution:
    def splitString(self, s: str) -> bool:
        n = len(s)

        def dfs(i, target):
            if i == n:
                return True
            for j in range(i, n):
                if int(s[i:j + 1]) == target and dfs(j + 1, target - 1):
                    return True
            return False

        return any(dfs(j + 1, int(s[:j + 1]) - 1) for j in range(n - 1))

