class Solution {
    private int n;
    private String s;

    public boolean splitString(String s) {
        this.s = s;
        n = s.length();
        for (int j = 1; j < n; j++)
            if (dfs(j, Long.parseLong(s.substring(0, j)) - 1)) return true;
        return false;
    }

    private boolean dfs(int i, long target) {
        if (i == n) return true;
        for (int j = i + 1; j <= n; j++)
            if (Long.parseLong(s.substring(i, j)) == target && dfs(j, target - 1)) return true;
        return false;
    }
}

