class Solution:
    def splitString(self, s: str) -> bool:
        n = len(s)
        dp = [set() for _ in range(n + 1)]
        for j in range(1, n):
            dp[j].add(int(s[:j]))
        for i in range(1, n):
            for j in range(i + 1, n + 1):
                w = int(s[i:j])
                if w + 1 in dp[i]:
                    dp[j].add(w)
        return len(dp[n]) > 0

