class Solution {
public:
    bool splitString(string s) {
        int n = s.size();
        vector<unordered_set<long long>> dp(n + 1);
        for (int j = 1; j < n; ++j) dp[j].insert(stoll(s.substr(0, j)));
        for (int i = 1; i < n; ++i)
            for (int j = i + 1; j <= n; ++j) {
                long long w = stoll(s.substr(i, j - i));
                if (dp[i].count(w + 1)) dp[j].insert(w);
            }
        return !dp[n].empty();
    }
};

