class Solution {
    public boolean splitString(String s) {
        int n = s.length();
        List<Set<Long>> dp = new ArrayList<>();
        for (int i = 0; i <= n; i++) dp.add(new HashSet<>());
        for (int j = 1; j < n; j++) dp.get(j).add(Long.parseLong(s.substring(0, j)));
        for (int i = 1; i < n; i++)
            for (int j = i + 1; j <= n; j++) {
                long w = Long.parseLong(s.substring(i, j));
                if (dp.get(i).contains(w + 1)) dp.get(j).add(w);
            }
        return !dp.get(n).isEmpty();
    }
}

